package com.archanalyzer.ai;

/**
 * Explanation of an architectural smell generated by Generative AI based strictly
 * on static analysis evidence.
 */
public class ArchitectureSmellExplanation {

    private final String smellType;
    private final String componentId;
    private final String evidence;
    private final String plainLanguageExplanation;
    private final String whyItMatters;
    private final String maintainabilityImpact;
    private final String recommendedAction;
    private final String priority; // HIGH, MEDIUM, LOW
    private final String confidence;

    public ArchitectureSmellExplanation(String smellType, String componentId, String evidence,
                                        String plainLanguageExplanation, String whyItMatters,
                                        String maintainabilityImpact, String recommendedAction,
                                        String priority, String confidence) {
        this.smellType = smellType;
        this.componentId = componentId;
        this.evidence = evidence;
        this.plainLanguageExplanation = plainLanguageExplanation;
        this.whyItMatters = whyItMatters;
        this.maintainabilityImpact = maintainabilityImpact;
        this.recommendedAction = recommendedAction;
        this.priority = priority != null ? priority : "MEDIUM";
        this.confidence = confidence != null ? confidence : "High";
    }

    public String getSmellType() { return smellType; }
    public String getComponentId() { return componentId; }
    public String getEvidence() { return evidence; }
    public String getPlainLanguageExplanation() { return plainLanguageExplanation; }
    public String getWhyItMatters() { return whyItMatters; }
    public String getMaintainabilityImpact() { return maintainabilityImpact; }
    public String getRecommendedAction() { return recommendedAction; }
    public String getPriority() { return priority; }
    public String getConfidence() { return confidence; }
}
